import { DT,descentStep,replayDescent } from './descent.js';
import { descentInitial,deltaV } from './engine.js';
export function mountDescent({flight,host,onSave,onFinish}){
  let controls=(flight.manualControls||[]).map(c=>[...c]),s=replayDescent(descentInitial(flight),controls),paused=true,throttle=.45,steer=0,raf=0,last=0,acc=0,done=false;
  host.innerHTML=`<section class="descent-station"><div class="section-title"><div><span class="label">FINAL 180 METRES / MANUAL CONTROL</span><h2>Bring it down gently.</h2></div><button class="button secondary" id="descent-pause">Start descent</button></div><p>Land within ±35 m of the beacon, below 3 m/s vertically and 2 m/s sideways. Tilt redirects thrust; too much tilt reduces vertical braking. Up/down changes throttle; left/right steers. P pauses.</p><canvas id="descent-canvas" width="1000" height="500" role="img" aria-label="Live lunar descent, with altitude and velocity reported below"></canvas><div class="descent-readouts" aria-live="off"></div><div class="descent-controls"><label>Throttle <output id="throttle-value">45%</output><input id="descent-throttle" type="range" min="0" max="100" value="45"></label><label>Horizontal thrust <select id="descent-steer"><option value="0">Vertical</option><option value="-1">Left</option><option value="1">Right</option></select></label></div><p id="descent-status" role="status">Paused. Set your controls, then start. Progress saves every second; leaving this screen pauses the attempt.</p><p class="tiny muted">Local 2D dynamics · 1.62 m/s² gravity · fixed 0.1 s integration · no atmosphere. This is a fictional flat landing zone, not a terrain map. The approach burn has already been allocated; final descent uses actual thrust and fuel.</p></section>`;
  const q=sel=>host.querySelector(sel),canvas=q('canvas'),ctx=canvas.getContext('2d'),pause=q('#descent-pause'),range=q('#descent-throttle'),select=q('#descent-steer');
  const cinema=document.querySelector('#flight-cinema'),viewport=document.createElement('div');viewport.className='manual-viewport';viewport.innerHTML='<span class="label">LUNAR DESCENT / LOCAL FLIGHT VIEW</span><h2>Keep the beacon beneath you.</h2><p class="muted">The green strip is your landing zone. The red lines mark the flight corridor.</p>';cinema.style.display='none';cinema.before(viewport);viewport.append(canvas);const status=document.createElement('p');status.className='descent-main-status';status.setAttribute('aria-live','polite');status.textContent='PAUSED · Set throttle and steering, then start descent.';viewport.append(status);
  function draw(){
    if(ctx){ctx.fillStyle='#080e15';ctx.fillRect(0,0,1000,500);ctx.fillStyle='#687682';for(let i=0;i<48;i++){ctx.fillRect((i*137)%1000,(i*61)%420,1.5,1.5);}ctx.fillStyle='#20282e';ctx.fillRect(0,440,1000,60);ctx.strokeStyle='#44505a';for(let x=0;x<1000;x+=70){ctx.beginPath();ctx.moveTo(x,440);ctx.lineTo(x+25,450);ctx.stroke();}const scale=.95,x=500+s.x*scale,y=440-s.y*.64;
      ctx.fillStyle='#b6efb6';ctx.fillRect(500-35*scale,437,70*scale,6);ctx.font='16px monospace';ctx.fillText('LANDING ZONE',435,478);ctx.setLineDash([4,6]);ctx.strokeStyle='#51615f';ctx.beginPath();ctx.moveTo(500,20);ctx.lineTo(500,435);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#915d51';ctx.setLineDash([7,8]);for(const bound of [-350,350]){ctx.beginPath();ctx.moveTo(500+bound*scale,30);ctx.lineTo(500+bound*scale,435);ctx.stroke();}ctx.setLineDash([]);
      if(s.status==='impact'){ctx.fillStyle='#ff9b55';ctx.beginPath();ctx.arc(x,y,30,0,Math.PI*2);ctx.fill();}else{ctx.save();ctx.translate(x,y);ctx.rotate(steer*.45);ctx.fillStyle='#b89b60';ctx.fillRect(-15,-23,30,23);ctx.strokeStyle='#edd49e';ctx.lineWidth=1;ctx.strokeRect(-15,-23,30,23);ctx.fillStyle='#b8c4cb';ctx.fillRect(-10,-30,20,7);ctx.fillStyle='#1f435e';ctx.fillRect(-42,-22,23,11);ctx.fillRect(19,-22,23,11);ctx.strokeStyle='#81a6be';ctx.lineWidth=.7;for(let i=0;i<3;i++){ctx.strokeRect(-42+i*8,-22,7,11);ctx.strokeRect(19+i*8,-22,7,11);}ctx.fillStyle='#777f83';ctx.beginPath();ctx.moveTo(-6,0);ctx.lineTo(-10,6);ctx.lineTo(10,6);ctx.lineTo(6,0);ctx.fill();ctx.strokeStyle='#ddd';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-10,-5);ctx.lineTo(-22,7);ctx.moveTo(10,-5);ctx.lineTo(22,7);ctx.stroke();if(!paused&&s.fuel>0&&throttle>0){ctx.fillStyle='#ff9f55';ctx.beginPath();ctx.moveTo(-7,0);ctx.lineTo(0,8+throttle*35);ctx.lineTo(7,0);ctx.fill();}ctx.restore();}}
    const bar=document.querySelector('.telemetry .meter-track i');if(bar)bar.style.width=`${s.fuel/flight.design.fuel*100}%`;const telemetry=document.querySelectorAll('.telemetry .telemetry-readout strong');if(telemetry[0])telemetry[0].innerHTML=`${s.fuel.toFixed(1)}<span>kg</span>`;if(telemetry[1])telemetry[1].innerHTML=`${Math.round(deltaV(s.dry+s.fuel,s.dry,s.isp))}<span>m/s</span>`;
    q('.descent-readouts').innerHTML=`<span>ALTITUDE <strong>${s.y.toFixed(1)} m</strong></span><span>VERTICAL <strong>${s.vy.toFixed(1)} m/s</strong></span><span>SIDEWAYS <strong>${s.vx.toFixed(1)} m/s</strong></span><span>OFFSET <strong>${s.x.toFixed(1)} m</strong></span><span>FUEL <strong>${s.fuel.toFixed(1)} kg</strong></span>`;
  }
  function persist(){flight.manualControls=controls.map(c=>[...c]);onSave();}
  function toggle(){paused=!paused;pause.textContent=paused?'Resume descent':'Pause descent';q('#descent-status').textContent=paused?'Paused. Your attempt is saved.':'Descent active. Keep your vertical and sideways speed under control.';status.textContent=paused?'PAUSED · Your attempt is saved.':'DESCENT ACTIVE · Brake early. Watch both velocities.';if(paused)persist();draw();}
  pause.onclick=toggle;range.oninput=()=>{throttle=Number(range.value)/100;q('#throttle-value').textContent=`${range.value}%`;};select.onchange=()=>{steer=Number(select.value);draw();};
  function key(e){if(document.querySelector('dialog[open]')||e.target.matches('input,select,textarea'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','p','P'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key.toLowerCase()==='p'){if(!e.repeat)toggle();return;}if(e.key==='ArrowUp'||e.key==='ArrowDown'){throttle=Math.max(0,Math.min(1,throttle+(e.key==='ArrowUp'?.05:-.05)));range.value=Math.round(throttle*100);q('#throttle-value').textContent=`${range.value}%`;}else{steer=e.key==='ArrowLeft'?-1:1;select.value=String(steer);}}}
  function release(e){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){steer=0;select.value='0';}}
  function visibility(){if(document.hidden&&!paused)toggle();}
  document.addEventListener('keydown',key,true);document.addEventListener('keyup',release);document.addEventListener('visibilitychange',visibility);
  function tick(now){const dt=Math.min(.1,(now-last)/1000||0);last=now;if(!paused&&!document.hidden){acc+=dt;while(acc>=DT&&s.status==='flying'){acc-=DT;const c=[throttle,steer];controls.push(c);s=descentStep(s,c);if(controls.length%10===0)persist();}draw();if(s.status!=='flying'){done=true;paused=true;q('#descent-status').textContent=s.reason;status.textContent=s.reason;host.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);draw();persist();onFinish({id:'manual-arrival',controls});return;}}raf=requestAnimationFrame(tick);}
  viewport.scrollIntoView({block:'start',behavior:'instant'});draw();raf=requestAnimationFrame(tick);pause.focus({preventScroll:true});
  return ()=>{cinema.style.display='';viewport.remove();cancelAnimationFrame(raf);document.removeEventListener('keydown',key,true);document.removeEventListener('keyup',release);document.removeEventListener('visibilitychange',visibility);if(!done)persist();};
}
